"""Human-readable connection between live code, counts and measured time."""
import json
from build import H
D=json.loads((H/'analysis/data.json').read_text());C=D['counts'];S=D['statistics'];M=D['metrics']
def c(k,r):return next(x for x in C if x['kind']==k and x['target']==r)
def t(k,l,r):return next(x['median_ms']/1000 for x in S if x['kind']==k and x['label']==l and x['target']==r)
text=['## 数据和执行路径怎么对应','','展示名“按需构造缓存”对应固定06aada4的SPARSE_CTOR_IC。本轮没有改缓存策略，只增加独立诊断接口；正式时间取原Release。原版A没有这里新增的解释器读IC和构造计划。','','### 属性读取','','A的ownRead缓冲区：`0000 get_arg0; 0001 get_field x; 0006 return`。按需版：`0000 v6_get_arg0; 0001 get_field_rdi delta=6→IC0; 0006 return`。IC0记录x对应的对象布局和槽号0。真实计时readLoop的同一读点在offset0017，前一条0016由get_loc0变成v6_get_loc0。这些数字来自执行后的byte_code_buf，JSON里保留原字节和位点数据。','','A的get_field调用find_own_property按属性名查找（shape中的属性哈希），不是扫描整个对象。按需版布局一致时直接读prop[0]。融合入口还越过后面的get_field_rdi分派，少做接收者的临时压栈和引用增减；序列取对象、循环判断、累加仍在。失配时走原普通属性查找并更新该位点，x的值和位置一直相同。','','本轮所有读命中都发生在融合入口。普通读取只数一次查询，融合成功也只数一次；每档query=N=hit+miss，hit=fused_hit+regular_hit。不能只看get_field_rdi入口，否则会漏掉融合命中。','',f"5次中位数：按需版从高命中{t('read','SPARSE',100):.3f}秒变为低命中{t('read','SPARSE',0):.3f}秒（+{M['read']['method_low_vs_high_pct']:.2f}%）；A相同输入变化{M['read']['A_low_vs_high_pct']:+.2f}%。",'','### 正计划构造','','同一个new C(3,0)位点：A的offset0018是call_constructor 2；按需版同处为four_ctor 0。0是缓存记录编号，该记录里argc=2，不是零参数。按需版ctorLoop的唯一new位点被注册并校验为一个静态点。构造器本体仍是相同的字段赋值字节码。','','正命中经four_ctor_try→plan_try，检查目标、原型、写资格和原GC/中断条件，按最终shape分配对象/属性存储，再由C循环将实参写入对应属性槽。它跳过普通JS_CallConstructorInternal入口、构造函数的解释器帧和逐条put_field/新增字段的过程。每个字段的原型写资格检查没有凭空消失，两个堆分配也仍在。失败就走原普通构造。','','两个不同身份的构造器赋值完全相同，共用原型；计时外保留空对象，确保空shape一直可用。这是控制输入，不是修改引擎学习规则。没有提前调用计时循环预热。','','| 正计划档位 | 查询 | 正命中 | 普通构造 | 实测正命中率 |','|---|---:|---:|---:|---:|']
for r in [0,50,100]:
 x=c('positive',r);text.append(f"| {r}% | {x['queries']:,} | {x['positive_or_read_hits']:,} | {x['misses_or_normal_constructions']:,} | {x['actual_hit_percent']:.8f}% |")
text+=['',f"高档开头仍有{c('positive',100)['misses_or_normal_constructions']}次普通构造，实测略低于100%。5次中位数：高命中{t('positive','SPARSE',100):.3f}秒、低命中{t('positive','SPARSE',0):.3f}秒，约{t('positive','SPARSE',0)/t('positive','SPARSE',100):.2f}倍；A相同输入变化{M['positive']['A_low_vs_high_pct']:+.2f}%。低命中比A慢{M['positive']['method_low_vs_A_pct']:.2f}%，高命中比A快{-M['positive']['method_high_vs_A_pct']:.2f}%。",'','### 负缓存对照','','将赋值改成this.x=x+0；本轮输入x始终是整数3，结果不变，但字节码在get_arg后有push_0/add，不符合纯参数写字段模板。两个目标都因这个模板不匹配而被拒绝。','','负命中经sparse_same，跳过plan_slow_eligible里的模板判型；后面照常调用JS_CallConstructorInternal。没有正计划命中，所有对象仍被分配、构造函数仍被调用。目标切换造成失配时，原SPARSE可能在学习资格和记住失败时各判断一次，因此低档判型入口次数接近2N。','','| 负档位 | 负命中 | 判型入口 | 普通构造 | 按需版中位数/秒 |','|---|---:|---:|---:|---:|']
for r in [0,50,100]:
 x=c('negative',r);text.append(f"| {r}% | {x['negative_hits']:,} | {x['template_entries']:,} | {x['misses_or_normal_constructions']:,} | {t('negative','SPARSE',r):.3f} |")
text+=['',f"本例负缓存把判型入口从{c('negative',0)['template_entries']:,}次降到{c('negative',100)['template_entries']}次，耗时{t('negative','SPARSE',0):.3f}→{t('negative','SPARSE',100):.3f}秒，有小幅收益。反向从高降到低为+{M['negative']['method_low_vs_high_pct']:.2f}%，远小于正计划的+{M['positive']['method_low_vs_high_pct']:.2f}%。不能把负命中当成省掉了构造。这里的7.3%来自同一按需版的高低档对照；它与A还差着原有读写优化，不能把对A的全部差距算成负缓存收益。",'','### 字节码、计数、时间各说明什么','','字节码标出执行入口与位点；计数证明这条快路确实被走到；Release时间回答整段循环到底快多少。本轮命中率下降时，读取和正计划构造都明显变慢；A相同输入变化很小。负缓存也有收益，但只省判型，幅度更小。','','原始快照见snapshots/的JSON、CSV与txt；读取C路径在read_ic_opcodes.inc及quickjs.c的V6_PREPARED_BORROW，正/负构造路径在four_runtime.inc与sparse_runtime.inc。诊断源码和补丁随实验一起保留。','','### 与真实全集的关系','','第6页只引用固定版本已有的Octane/SunSpider数据：相对历史A分别-7.86%/-4.45%，跨批次单轮筛选，本轮未重跑。小程序有意反复使用某一条快路，收益不能直接当成全集收益。11月9日旧属性实验也显示A大致平、IC随命中率提高而变快；本轮图表和数字全部来自本轮A/按需版测量，不混入旧点。','']
(H/'evidence.md').write_text('\n'.join(text))
p=H/'results.md';s=p.read_text();s=s.split('\n## 数据和执行路径怎么对应')[0];p.write_text(s+'\n'+'\n'.join(text));print('EVIDENCE_WRITTEN')
